-- 00_PRECHECK — 조회 전용. [E20261009-DMF0082GTTSTATS] 클라우드 DMF0082 GTT 통계 상태 · 나쁜 계획 커서 존재 판정
-- * [G1] 6 GTT 의 현재 통계(NUM_ROWS)·PREF — NUM_ROWS 비어 있고 PREF SESSION 이면 미적용(기대)
-- * [G2] 지금 V$SQL 에 남은 PKG_DMF0082 문장별 자식 커서·PHV·1회 소요 — 20초↑ 자식이 나쁜 계획(c3bg 카르테시안 248268428 · d019 3633386171 · 6bucw 1149543853)
-- * [G3] 사내 적용본 계획 PHV 참고: c3bg6q8n39195=294698915 · d019r0hbb0muh=2054382907 · 6bucw2kzuc0nt=1088113275 · 18xg1y5298qgq=3971101268
-- * [G4] GTT 를 GATHER 하는 객체(0 이어야 LOCK 없는 통계 고정이 충돌 없음) · 지금 PKG_DMF0082 실행 중 세션
SET LINESIZE 300 PAGESIZE 200
SELECT 'G0' CHK, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, SYS_CONTEXT('USERENV','INSTANCE_NAME') INST, TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') NOW FROM DUAL;
SELECT 'G1' CHK, T.TABLE_NAME, T.NUM_ROWS, T.BLOCKS, TO_CHAR(T.LAST_ANALYZED,'MM-DD HH24:MI') ANALYZED, S.STATTYPE_LOCKED LOCKED,
       DBMS_STATS.GET_PREFS('GLOBAL_TEMP_TABLE_STATS', 'SCM_MGR', T.TABLE_NAME) GTT_PREF,
       CASE WHEN T.NUM_ROWS IS NULL THEN '미적용 → 10 실행' WHEN DBMS_STATS.GET_PREFS('GLOBAL_TEMP_TABLE_STATS','SCM_MGR',T.TABLE_NAME)='SHARED' THEN '적용됨(10 재실행은 멱등)' ELSE '⚠ 세션 통계 잔존 — 10 실행 시 SHARED 로 전환' END JUDGE
  FROM USER_TABLES T LEFT JOIN USER_TAB_STATISTICS S ON S.TABLE_NAME = T.TABLE_NAME AND S.OBJECT_TYPE = 'TABLE'
 WHERE T.TABLE_NAME IN ('GT_DMF0082_TEMP_SITE_ITEM','GT_DMF0082_TEMP_SELECT_MEASURE','GT_DMF0082_T_WS_FCST','GT_DMF0082_TEMP_FCST_N_PRICE','GT_DMF0082_T_LAST_DATA_SETUP_FCST','GT_DMF0082_MF_SP')
 ORDER BY T.TABLE_NAME;
SELECT 'G2' CHK, S.INST_ID, S.SQL_ID, S.CHILD_NUMBER CH, S.PLAN_HASH_VALUE PHV, S.EXECUTIONS EX, ROUND(S.ELAPSED_TIME/1e6/GREATEST(S.EXECUTIONS,1),1) SEC_PER_EX,
       ROUND(S.BUFFER_GETS/GREATEST(S.EXECUTIONS,1)) BG_PER_EX, S.USERS_EXECUTING NOW_RUN, S.LAST_LOAD_TIME LOADED,
       CASE WHEN S.PLAN_HASH_VALUE IN (248268428, 3633386171, 1149543853) THEN '❌ 10-09 타임아웃 계획' WHEN S.ELAPSED_TIME/GREATEST(S.EXECUTIONS,1) > 20e6 THEN '⚠ 20초↑' ELSE '' END JUDGE
  FROM GV$SQL S WHERE S.SQL_ID IN ('c3bg6q8n39195','d019r0hbb0muh','6bucw2kzuc0nt','18xg1y5298qgq','631pzfvq8r0ut','4svg4dhnqxh8f','20xrvz802rfsy','19mfxqb34sbky','56fkh52zfndm7')
 ORDER BY S.SQL_ID, S.INST_ID, S.CHILD_NUMBER;
SELECT 'G4-GATHER' CHK, NAME, TYPE, COUNT(*) N FROM ALL_SOURCE WHERE OWNER = 'SCM_MGR' AND REGEXP_LIKE(TEXT,'GATHER_TABLE_STATS','i') AND TRIM(TEXT) NOT LIKE '--%' AND TRIM(TEXT) NOT LIKE 'NULL;%'
   AND REGEXP_LIKE(TEXT, 'GT_DMF0082_(TEMP_SITE_ITEM|TEMP_SELECT_MEASURE|T_WS_FCST|TEMP_FCST_N_PRICE|T_LAST_DATA_SETUP_FCST|MF_SP)\b')
 GROUP BY NAME, TYPE;
SELECT 'G4-RUNNING' CHK, S.INST_ID, S.SID, S.SERIAL#, S.USERNAME, S.MACHINE, S.LAST_CALL_ET CALL_SEC, S.SQL_ID, S.EVENT
  FROM GV$SESSION S WHERE S.TYPE = 'USER' AND S.STATUS = 'ACTIVE'
   AND S.PLSQL_ENTRY_OBJECT_ID = (SELECT OBJECT_ID FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0082' AND OBJECT_TYPE = 'PACKAGE')
 ORDER BY S.LAST_CALL_ET DESC;
